SQL = "CREATE EXTENSION IF NOT EXISTS btree_gist;\nALTER TABLE lesson_calendar_resourcebooking ADD CONSTRAINT calendar_booking_no_overlap\nEXCLUDE USING gist (resource_id WITH =, tstzrange(start_at,end_at,'[)') WITH &&)\nDEFERRABLE INITIALLY IMMEDIATE;\n\nCREATE FUNCTION calendar_assert_lesson(target uuid) RETURNS void LANGUAGE plpgsql AS $$\nDECLARE l lesson_calendar_lessonoccurrence%ROWTYPE; payload jsonb; unit jsonb;\n pause_min integer; space_min integer; video_min integer; n integer; expected_n integer;\n needs_space boolean; needs_video boolean; expected_students text[]; actual_students text[];\nBEGIN\n SELECT * INTO l FROM lesson_calendar_lessonoccurrence WHERE id=target;\n IF NOT FOUND THEN RETURN; END IF;\n IF l.state <> 'PUBLISHED' THEN\n   IF EXISTS(SELECT 1 FROM lesson_calendar_resourcebooking WHERE lesson_id=target) THEN\n     RAISE EXCEPTION 'Cancelled lesson retains bookings' USING ERRCODE='23514';\n   END IF; RETURN;\n END IF;\n SELECT s.data INTO payload FROM lesson_calendar_publication p\n JOIN scheduling_scheduleplan pl ON pl.id=p.plan_id JOIN scheduling_schedulerun r ON r.id=pl.run_id\n JOIN scheduling_planningsnapshot s ON s.id=r.snapshot_id WHERE p.id=l.publication_id;\n SELECT value INTO unit FROM jsonb_array_elements(payload->'units') WHERE value->>'demand_key'=(SELECT demand_key FROM scheduling_demandunit WHERE id=l.demand_id);\n IF unit IS NULL OR (unit->>'subject')<>l.subject_id::text OR\n    l.end_at-l.start_at<>make_interval(mins=>(unit->>'duration_minutes')::integer) OR\n    NOT ((unit->'allowed_tutors') ? l.tutor_id::text) OR NOT ((unit->'allowed_modes') ? l.mode) THEN\n   RAISE EXCEPTION 'Lesson inconsistent with canonical snapshot unit' USING ERRCODE='23514';\n END IF;\n SELECT array_agg(value ORDER BY value) INTO expected_students FROM jsonb_array_elements_text(unit->'participants');\n SELECT array_agg(student_id::text ORDER BY student_id::text) INTO actual_students FROM lesson_calendar_lessonparticipant WHERE lesson_id=target;\n IF actual_students IS DISTINCT FROM expected_students THEN\n   RAISE EXCEPTION 'Participants inconsistent with materialized snapshot' USING ERRCODE='23514';\n END IF;\n SELECT (value->>'pause_minutes')::integer INTO pause_min FROM jsonb_array_elements(payload->'tutors') WHERE value->>'id'=l.tutor_id::text;\n IF pause_min IS NULL OR l.tutor_occupied_until IS DISTINCT FROM l.end_at+make_interval(mins=>pause_min) THEN\n   RAISE EXCEPTION 'Tutor occupation inconsistent with policy' USING ERRCODE='23514';\n END IF;\n needs_space := l.mode='IN_PERSON' OR (l.location='ON_SITE' AND (payload->>'online_onsite_requires_space')::boolean);\n needs_video := l.mode='ONLINE' AND (payload->>'video_channels_required')::boolean;\n IF needs_space IS DISTINCT FROM (l.space_id IS NOT NULL) OR needs_video IS DISTINCT FROM (l.video_id IS NOT NULL) THEN\n   RAISE EXCEPTION 'Required resource missing or unexpected' USING ERRCODE='23514';\n END IF;\n IF l.space_id IS NOT NULL THEN\n   SELECT (value->>'buffer_minutes')::integer INTO space_min FROM jsonb_array_elements(payload->'resources') WHERE value->>'id'=l.space_id::text AND value->>'kind'='SPACE';\n   IF space_min IS NULL OR l.space_occupied_until IS DISTINCT FROM l.end_at+make_interval(mins=>space_min) OR\n     NOT EXISTS(SELECT 1 FROM education_resource WHERE id=l.space_id AND kind='SPACE') THEN\n     RAISE EXCEPTION 'Space occupation inconsistent' USING ERRCODE='23514';\n   END IF;\n   IF l.mode='IN_PERSON' AND cardinality(actual_students)>(SELECT student_capacity FROM education_resource WHERE id=l.space_id) THEN\n     RAISE EXCEPTION 'Space capacity exceeded' USING ERRCODE='23514';\n   END IF;\n END IF;\n IF l.video_id IS NOT NULL THEN\n   SELECT (value->>'buffer_minutes')::integer INTO video_min FROM jsonb_array_elements(payload->'resources') WHERE value->>'id'=l.video_id::text AND value->>'kind'='VIDEO_CHANNEL';\n   IF video_min IS NULL OR l.video_occupied_until IS DISTINCT FROM l.end_at+make_interval(mins=>video_min) OR\n     NOT EXISTS(SELECT 1 FROM education_resource WHERE id=l.video_id AND kind='VIDEO_CHANNEL') THEN\n     RAISE EXCEPTION 'Video occupation inconsistent' USING ERRCODE='23514';\n   END IF;\n END IF;\n SELECT count(*) INTO n FROM lesson_calendar_resourcebooking WHERE lesson_id=target;\n expected_n := 1+cardinality(actual_students)+(l.space_id IS NOT NULL)::integer+(l.video_id IS NOT NULL)::integer;\n IF n<>expected_n OR EXISTS(\n SELECT 1 FROM lesson_calendar_resourcebooking b JOIN lesson_calendar_calendarresource c ON c.id=b.resource_id\n WHERE b.lesson_id=target AND (b.start_at=l.start_at AND (\n  (c.kind='TUTOR' AND c.tutor_id=l.tutor_id AND b.end_at=l.tutor_occupied_until) OR\n  (c.kind='STUDENT' AND b.end_at=l.end_at AND c.student_id IN (SELECT student_id FROM lesson_calendar_lessonparticipant WHERE lesson_id=target)) OR\n  (c.kind='RESOURCE' AND c.resource_id=l.space_id AND b.end_at=l.space_occupied_until) OR\n  (c.kind='RESOURCE' AND c.resource_id=l.video_id AND b.end_at=l.video_occupied_until))) IS NOT TRUE) THEN\n   RAISE EXCEPTION 'Incomplete or inconsistent resource bookings' USING ERRCODE='23514';\n END IF;\nEND $$;\nCREATE FUNCTION calendar_check_trigger() RETURNS trigger LANGUAGE plpgsql AS $$\nDECLARE old_id uuid; new_id uuid;\nBEGIN\n IF TG_TABLE_NAME='lesson_calendar_lessonoccurrence' THEN\n  IF TG_OP<>'INSERT' THEN old_id:=OLD.id; END IF; IF TG_OP<>'DELETE' THEN new_id:=NEW.id; END IF;\n ELSE\n  IF TG_OP<>'INSERT' THEN old_id:=OLD.lesson_id; END IF; IF TG_OP<>'DELETE' THEN new_id:=NEW.lesson_id; END IF;\n END IF;\n IF old_id IS NOT NULL THEN PERFORM calendar_assert_lesson(old_id); END IF;\n IF new_id IS NOT NULL AND new_id IS DISTINCT FROM old_id THEN PERFORM calendar_assert_lesson(new_id); END IF;\n RETURN NULL;\nEND $$;\nCREATE CONSTRAINT TRIGGER calendar_verify_lesson AFTER INSERT OR UPDATE OR DELETE ON lesson_calendar_lessonoccurrence DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION calendar_check_trigger();\nCREATE CONSTRAINT TRIGGER calendar_verify_booking AFTER INSERT OR UPDATE OR DELETE ON lesson_calendar_resourcebooking DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION calendar_check_trigger();\nCREATE CONSTRAINT TRIGGER calendar_verify_participant AFTER INSERT OR UPDATE OR DELETE ON lesson_calendar_lessonparticipant DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION calendar_check_trigger();\nCREATE FUNCTION calendar_resource_identity_guard() RETURNS trigger LANGUAGE plpgsql AS $$\nBEGIN\n IF EXISTS(SELECT 1 FROM lesson_calendar_resourcebooking WHERE resource_id=OLD.id) AND\n (NEW.kind IS DISTINCT FROM OLD.kind OR NEW.tutor_id IS DISTINCT FROM OLD.tutor_id OR NEW.student_id IS DISTINCT FROM OLD.student_id OR NEW.resource_id IS DISTINCT FROM OLD.resource_id) THEN\n  RAISE EXCEPTION 'Booked resource identity is immutable' USING ERRCODE='23514';\n END IF; RETURN NEW;\nEND $$;\nCREATE TRIGGER calendar_resource_identity BEFORE UPDATE ON lesson_calendar_calendarresource FOR EACH ROW EXECUTE FUNCTION calendar_resource_identity_guard();\n"
